const fs = require("node:fs");
const path = require("node:path");

const projectRoot = path.resolve(__dirname, "..");
const sqlPath = path.join(
  projectRoot,
  "src",
  "infrastructure",
  "db",
  "migrations",
  "001_initial_schema.sql",
);
const generatedPath = path.join(
  projectRoot,
  "src",
  "infrastructure",
  "db",
  "migrations",
  "001-initial-schema.ts",
);

const sql = fs.readFileSync(sqlPath, "utf8").replaceAll("\r\n", "\n");
const generated = [
  "// Generated from 001_initial_schema.sql. Do not edit this file directly.",
  "// prettier-ignore",
  `export const INITIAL_SCHEMA_SQL = ${JSON.stringify(sql)};`,
  "",
].join("\n");

if (process.argv.includes("--check")) {
  const current = fs
    .readFileSync(generatedPath, "utf8")
    .replaceAll("\r\n", "\n");
  if (current !== generated) {
    console.error("Migration bundle is stale. Run: npm run migration:generate");
    process.exitCode = 1;
  }
} else {
  fs.writeFileSync(generatedPath, generated, "utf8");
}
